begin;
create temporary table lf05_first_six(
id text,course_id text,paper_number smallint,topic_id text,skill_ref text,title text,
question_prompt text,stimulus text,marks_style smallint,guidance jsonb,
approved_source_ref text,approved_review_ref text) on commit drop;
insert into lf05_first_six values
('BUS-LF05-01-25','aqa:aqa-a-level:7132',1,'business','AQA 7132 v2.0 §3.1.1','Survival versus business objectives','To what extent should survival be the most important objective for a small business operating in an increasingly competitive market?',NULL,25,'["AO1 selected knowledge: Differentiate accounting profit, cash flow and business objectives, including survival, growth and social objectives. Extend accurately into the concepts named in the question, with appropriately precise business terminology.","AO2 plausible business contexts: Illustrate the argument using contrasting relevant businesses or reasoned hypothetical contexts; Paper 1 does not necessarily supply an individual case. Specific, coherent application is preferable to an unsubstantiated named brand.","AO3 developed analysis: Develop two coherent arguments: survival limits risk and safeguards stakeholder commitments; excessive caution can sacrifice scale, customers and long-run competitiveness. Compare survival, profit, cash flow and growth, explaining interrelationships rather than listing objectives.","AO4 balanced judgement: Judge using stage of life, competition, finance available, external shocks and owner preferences; explain conditions under which another objective should take precedence.","Valid alternatives: A well-argued counter-position can reach the highest level. Credit evidence-backed qualifications and alternative causal pathways; do not require a prewritten conclusion.","Level discriminator: High-band answers sustain two or more developed competing arguments, refer consistently to realistic context, weigh their relative significance and reach a comparative conclusion responsive to To what extent. Mid-band answers may analyse well but reach a weak/conditional-but-unexplained overall judgement; low-band answers list general advantages and disadvantages."]'::jsonb,'PR834 675fdc8c53a224fe8fa9a81079b57b15dafef7af; AQA 7132 v2.0 §3.1.1; original question','AI A3 43620992688 receipt 14124482254 PASS/PASS BUS-LF05-01-25 675fdc8c53a224fe8fa9a81079b57b15dafef7af'),
('BUS-LF05-02-16','aqa:aqa-a-level:7132',2,'leadership','AQA 7132 v2.0 §3.2.1','Larch Medical Supplies: leadership','Evaluate whether Larch Medical Supplies should adopt a more democratic leadership style.','Larch Medical Supplies employs 220 people across two sites. Staff turnover rose from 12% to 21% after its director introduced centralised shifts; orders are 15% late. Workers want consultation, but the director argues decisions must be fast.',16,'["AO1 accurate concepts: Differentiate autocratic and democratic leadership and relate managerial decision making to goals.","AO2 contextual selection and interpretation: Use 21% turnover, late orders and the centralised shift change; show how consultation could change scheduling and commitment.","AO3 developed causal analysis: Analyse faster local problem solving and stronger motivation against consultation cost and decision delay. Explain why the optimal style may vary by urgency, expertise and organisational culture.","AO4 evaluation and judgement: Recommend a bounded more participative approach for shift planning while retaining clear authority during emergencies; identify success measures.","Valid alternatives: Reward a different recommendation if its assumptions and analysis are coherent with the facts; do not require the example''s suggested conclusion. Penalise unsupported inference and calculations not justified by the stimulus, not a different but defensible business choice.","Level discriminator: A 13–16-quality response integrates multiple actual facts from this specific case, develops at least two competing causal chains and prioritises a qualified conclusion. A 5–8-quality response mainly describes an idea and cites a fact without analysing its consequences. The exact band decision requires calibrated reviewed exemplars."]'::jsonb,'PR834 675fdc8c53a224fe8fa9a81079b57b15dafef7af; AQA 7132 v2.0 §3.2.1; original question','AI A3 43620992688 receipt 14124482254 PASS/PASS BUS-LF05-02-16 675fdc8c53a224fe8fa9a81079b57b15dafef7af'),
('BUS-LF05-02-25','aqa:aqa-a-level:7132',1,'leadership','AQA 7132 v2.0 §3.2.1–3.2.3','Leadership versus decision methods','To what extent is effective leadership more important than formal decision-making methods for a growing business?',NULL,25,'["AO1 selected knowledge: Differentiate autocratic and democratic leadership and relate managerial decision making to goals. Extend accurately into the concepts named in the question, with appropriately precise business terminology.","AO2 plausible business contexts: Illustrate the argument using contrasting relevant businesses or reasoned hypothetical contexts; Paper 1 does not necessarily supply an individual case. Specific, coherent application is preferable to an unsubstantiated named brand.","AO3 developed analysis: Explain mechanisms by which leadership enables execution, cultural change and stakeholder trust. Compare systematic decisions using data/decision trees and leader judgement under time pressure and uncertainty.","AO4 balanced judgement: Use qualification/context-sensitive judgement, not a universal leader-versus-method slogan; explain how a well-chosen style supports robust evidence-based decision making.","Valid alternatives: A well-argued counter-position can reach the highest level. Credit evidence-backed qualifications and alternative causal pathways; do not require a prewritten conclusion.","Level discriminator: High-band answers sustain two or more developed competing arguments, refer consistently to realistic context, weigh their relative significance and reach a comparative conclusion responsive to To what extent. Mid-band answers may analyse well but reach a weak/conditional-but-unexplained overall judgement; low-band answers list general advantages and disadvantages."]'::jsonb,'PR834 675fdc8c53a224fe8fa9a81079b57b15dafef7af; AQA 7132 v2.0 §3.2.1–3.2.3; original question','AI A3 43620992688 receipt 14124482254 PASS/PASS BUS-LF05-02-25 675fdc8c53a224fe8fa9a81079b57b15dafef7af'),
('BUS-LF05-03-25','aqa:aqa-a-level:7132',1,'marketing','AQA 7132 v2.0 §3.3.1–3.3.4','Marketing research versus marketing mix','To what extent is accurate marketing research more important than an effective marketing mix when launching a new product?',NULL,25,'["AO1 selected knowledge: Define segmentation, targeting, positioning and relevant product, price, promotion and place decisions. Extend accurately into the concepts named in the question, with appropriately precise business terminology.","AO2 plausible business contexts: This is a standalone original Paper 1 25-mark-style training essay; no supplied case is automatically compulsory. Credit internally consistent, conditional examples of launches (e.g. specialist unfamiliar versus established repeat-purchase markets), with realistic target buyers, research quality and marketing-mix execution. A famous brand name without causal case-specific application is not sufficient. Proposed numeric AOs are historical authoring guidance only, not an independently verified 2027 item-level mark scheme.","AO3 developed analysis: Explain how research reduces launch uncertainty yet sampling, extrapolation and reliability limit forecasts. Show how integrated product, price, place and promotion can succeed or fail even with accurate information.","AO4 balanced judgement: Judge whether information quality or execution is the binding constraint, with new versus established markets and launch budget considered.","Valid alternatives: A well-argued counter-position can reach the highest level. Credit evidence-backed qualifications and alternative causal pathways; do not require a prewritten conclusion.","Level discriminator: High-band answers sustain two or more developed competing arguments, refer consistently to realistic context, weigh their relative significance and reach a comparative conclusion responsive to To what extent. Mid-band answers may analyse well but reach a weak/conditional-but-unexplained overall judgement; low-band answers list general advantages and disadvantages."]'::jsonb,'PR834 675fdc8c53a224fe8fa9a81079b57b15dafef7af; AQA 7132 v2.0 §3.3.1–3.3.4; original question','AI A3 43620992688 receipt 14124482254 PASS/PASS BUS-LF05-03-25 675fdc8c53a224fe8fa9a81079b57b15dafef7af'),
('BUS-LF05-10-25','aqa:aqa-a-level:7132',1,'strategic-change','AQA 7132 v2.0 §3.10','Culture and strategic change','To what extent is organisational culture the most important influence on successful strategic change?',NULL,25,'["AO1 selected knowledge: Explain strategic change, resistance, consultation, organisational culture and implementation planning. Extend accurately into the concepts named in the question, with appropriately precise business terminology.","AO2 plausible business contexts: Illustrate the argument using contrasting relevant businesses or reasoned hypothetical contexts; Paper 1 does not necessarily supply an individual case. Specific, coherent application is preferable to an unsubstantiated named brand.","AO3 developed analysis: Develop how values/norms influence adoption, motivation and coordination during change. Compare leadership, resources, communication, technology readiness, stakeholder pressure and strategic fit.","AO4 balanced judgement: Judge when culture is dominant versus financial/resources or external market constraints; discuss interaction and time horizon.","Valid alternatives: A well-argued counter-position can reach the highest level. Credit evidence-backed qualifications and alternative causal pathways; do not require a prewritten conclusion.","Level discriminator: High-band answers sustain two or more developed competing arguments, refer consistently to realistic context, weigh their relative significance and reach a comparative conclusion responsive to To what extent. Mid-band answers may analyse well but reach a weak/conditional-but-unexplained overall judgement; low-band answers list general advantages and disadvantages."]'::jsonb,'PR834 675fdc8c53a224fe8fa9a81079b57b15dafef7af; AQA 7132 v2.0 §3.10; original question','AI A3 43620992688 receipt 14124482254 PASS/PASS BUS-LF05-10-25 675fdc8c53a224fe8fa9a81079b57b15dafef7af'),
('PSY-LF05-01-S1','aqa:aqa-a-level:7182',1,'social-influence','AQA 7182 v1.4 §4.1.1','Council: resistance to social influence','Discuss explanations for resistance to social influence, using the situation above in your answer.','At a sixth-form council meeting, seven student representatives are asked by the college organiser to support a proposed timetable change. Leila privately thinks the change is unfair. At first she stays silent while other representatives agree. When another student openly objects, Leila says that she also disagrees and explains why. Later Leila says that she prefers to make decisions based on her own judgement rather than simply following the group.',16,'["AO1 / knowledge: Explain social support as a route to resisting conformity and, if used, authority pressure. Explain locus of control as an account of perceived personal control and the tendency to take responsibility for choices. Correctly distinguish resistance from mere agreement and describe the two explanations without treating them as identical.","AO2 / the actual scenario: Leila initially stays silent despite disagreement, an ally speaks first, and Leila then objects: this supports possible social support reducing unanimity and fear of standing alone. Her later reported preference for independent judgement may be consistent with an internal locus of control; it is not proof of her measured locus of control. The organiser''s request provides authority context but does not demonstrate why she originally complied.","AO3 / reasoned evaluation: Evaluate evidence and limits of experimental findings about allies, including controlled-setting generalisation. Examine whether locus of control explains resistance consistently or changes with setting and social norms. Compare situational and dispositional explanations and form a qualified judgement about their relative contributions.","Alternative credit: A supported explanation involving the visibility of dissent, changes in perceived group unanimity or confidence may be creditworthy when explicitly connected to social support. Some answers may distinguish conformity and obedience, provided the distinction stays anchored to this specific situation. Do not require one named classic study if a logically accurate and relevant explanation is supplied.","What would weaken the answer: claiming Leila''s self-report proves high internal locus of control, stating that one dissenter always causes resistance, listing conformity/obedience experiments with no connection to her response, or giving generic evaluation that does not answer the command.","Useful self-review questions (only after attempt): Did I explain both named mechanisms correctly? Did I use specific facts from the council scene? Did I evaluate the explanations instead of only describing them? Did I avoid treating the scenario as experimental proof?","Qualitative differentiation, not a calibrated grade: A stronger answer integrates both mechanisms, precise scenario application, evidence-sensitive objections and a qualified overall judgement. A developing answer explains one mechanism well but offers little direct scenario use or evaluation. A limited answer mainly retells the story or lists unsupported keywords."]'::jsonb,'PR834 675fdc8c53a224fe8fa9a81079b57b15dafef7af; AQA 7182 v1.4 §4.1.1; original question','AI A3 43620992688 receipt 14124482254 PASS/PASS PSY-LF05-01-S1 675fdc8c53a224fe8fa9a81079b57b15dafef7af');
insert into public.lf05_written_questions
(id,course_id,paper_number,topic_id,skill_ref,title,question_prompt,stimulus,marks_style,content_fingerprint,original_training_only,status,approved_source_ref)
select id,course_id,paper_number,topic_id,skill_ref,title,question_prompt,stimulus,marks_style,
encode(sha256(convert_to(id||chr(31)||question_prompt||chr(31)||coalesce(stimulus,'')||chr(31)||guidance::text,'UTF8')),'hex'),
true,'published',approved_source_ref from lf05_first_six;
insert into public.lf05_written_guides (question_id,content_fingerprint,guidance,approved_review_ref)
select q.id,q.content_fingerprint,s.guidance,s.approved_review_ref from lf05_first_six s
join public.lf05_written_questions q on q.id=s.id;
-- The publication flag does not create admission: lf05_private.lf05_test_memberships
-- remains empty and is checked live for every original stem, guide and essay API.
commit;
